import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print("No common prefux exists")
        return

    parts = data[0].split()
    if len(parts) < 2:
        print("No common prefux exists")
        return

    try:
        n = int(parts[0])
    except:
        print("No common prefux exists")
        return

    if n == 0:
        print("No common prefux exists")
        return

    strings = []
    for i in range(1, n + 1):
        if i < len(data):
            strings.append(data[i].strip())

    if not strings:
        print("No common prefux exists")
        return

    # Extract odd-indexed strings (1st, 3rd, 5th, ...) - using 0-based indexing
    odd_strings = [strings[i] for i in range(0, n, 2)]

    # Extract even-indexed strings (2nd, 4th, 6th, ...) - using 0-based indexing
    even_strings = [strings[i] for i in range(1, n, 2)]

    # Handle edge cases
    if not odd_strings:
        print("No common prefux exists")
        return

    # Find common prefix of odd strings
    if odd_strings:
        min_odd_len = min(len(s) for s in odd_strings)
        common_prefix = []
        for j in range(min_odd_len):
            char = odd_strings[0][j]
            if all(s[j] == char for s in odd_strings):
                common_prefix.append(char)
            else:
                break

        if not common_prefix:
            print("No common prefux exists")
            return

        result = ''.join(common_prefix)

        # Check against even strings (reversed suffix)
        for s in even_strings:
            if not s:
                print("No common prefux exists")
                return
            if result not in s:
                print("No common prefux exists")
                return

            # Find the rightmost occurrence in even string
            idx = s.rfind(result)
            if idx == -1:
                print("No common prefux exists")
                return

            # Truncate to valid length
            valid_len = len(result)
            for i, c in enumerate(result):
                if idx + i >= len(s) or s[idx + i] != c:
                    valid_len = i
                    break

            if valid_len < len(result):
                result = result[:valid_len]

        if result:
            print(result)
        else:
            print("No common prefux exists")
    else:
        print("No common prefux exists")

if __name__ == "__main__":
    main()
